package com.wissenup.domain.fee.entity; import jakarta.persistence.*;import lombok.*;import java.time.*;import java.math.*;
@Entity @Table(name="fee_structures") @Getter@Setter@Builder@NoArgsConstructor@AllArgsConstructor public class FeeStructure{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="fee_structure_id")private Long feeStructureId;@Column(name="organization_id")private Long organizationId;@Column(name="academic_year_id")private Long academicYearId;@Column(name="class_id")private Long classId;@Column(name="fee_type_id")private Long feeTypeId;private BigDecimal amount;@Column(name="due_date")private LocalDate dueDate;@Column(name="due_day")private Integer dueDay;private String frequency;private String status;@Column(name="created_at")private LocalDateTime createdAt;@Column(name="created_by")private Long createdBy;@Column(name="updated_at")private LocalDateTime updatedAt;@Column(name="updated_by")private Long updatedBy;@PrePersist void c(){if(status==null)status="ACTIVE";if(createdAt==null)createdAt=LocalDateTime.now();}@PreUpdate void u(){updatedAt=LocalDateTime.now();}}
